#[test]
fn test_a_date_of_digits_is_found_and_written_out() {
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    sft_run(&crate::testport::text_blob("PAID 2026-03-14")[..], et, out, 2, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 1, "year first, one separator: a date nothing disputes");
    crate::testport::assert_eq(crate::port::cells_at(out, 3), 5, "it starts after PAID");
    crate::testport::assert_eq(crate::port::cells_at(out, 4), 10, "and is ten characters");
    crate::testport::assert_eq(crate::port::cells_at(out, 5), 2026, "the year");
    crate::testport::assert_eq(crate::port::cells_at(out, 6), 3, "the month");
    crate::testport::assert_eq(crate::port::cells_at(out, 7), 14, "the day");
    sft_run(&crate::testport::text_blob("Date: 2026/4/2.")[..], et, out, 2, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 6), 4, "a slash and one-digit parts");
    crate::testport::assert_eq(crate::port::cells_at(out, 7), 2, "the day, 2");
    sft_run(&crate::testport::text_blob("14.03.2026")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 1, "a day over 12 first: the day, then the month");
    crate::testport::assert_eq(crate::port::cells_at(out, 6), 3, "month 3");
    crate::testport::assert_eq(crate::port::cells_at(out, 7), 14, "day 14");
    sft_run(&crate::testport::text_blob("03/14/2026")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 6), 3, "a second number over 12 is the day, whatever the order");
    crate::testport::assert_eq(crate::port::cells_at(out, 7), 14, "so the first is the month");
    sft_run(&crate::testport::text_blob("03/04/2026")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 2, "both numbers at most 12 and with no hint: the text as it stands");
    crate::testport::assert_eq(crate::port::cells_at(out, 4), 10, "its ten characters");
    sft_run(&crate::testport::text_blob("03/04/2026")[..], et, out, 1, 2);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 1, "month first by the hint");
    crate::testport::assert_eq(crate::port::cells_at(out, 6), 3, "month 3");
    crate::testport::assert_eq(crate::port::cells_at(out, 7), 4, "day 4");
    sft_run(&crate::testport::text_blob("03/04/2026")[..], et, out, 1, 1);
    crate::testport::assert_eq(crate::port::cells_at(out, 6), 4, "day first by the hint: month 4");
    crate::testport::assert_eq(crate::port::cells_at(out, 7), 3, "day 3");
    sft_run(&crate::testport::text_blob("05/05/2026")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 1, "the same number twice is the same either way");
    sft_run(&crate::testport::text_blob("SEALED 12.5.24")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 2, "a two-digit year is a date's shape only: as it stands");
    sft_run(&crate::testport::text_blob("NO DIGITS HERE")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 0, "a text with no digits has no date");
    sft_run(&crate::testport::text_blob("REG 20261 AND 99")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 0, "numbers that are no date shape are none");
    sft_run(&crate::testport::text_blob("2026-13-40")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 0, "a month of 13 is no date");
}
#[test]
fn test_a_date_of_other_scripts_and_words_is_found() {
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    sft_run(&crate::testport::text_blob("北京市 2026年3月14日 公章")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 1, "the CJK year, month and day marks");
    crate::testport::assert_eq(crate::port::cells_at(out, 5), 2026, "the year");
    crate::testport::assert_eq(crate::port::cells_at(out, 6), 3, "the month");
    crate::testport::assert_eq(crate::port::cells_at(out, 7), 14, "the day");
    crate::testport::assert_eq(crate::port::cells_at(out, 3), 4, "it starts after the city and a space");
    sft_run(&crate::testport::text_blob("서울 2026년 03월 14일")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 0, "Hangul marks with spaces between are not read (no guessing)");
    sft_run(&crate::testport::text_blob("٢٠٢٦-٠٣-١٤")[..], et, out, 2, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 1, "Arabic-Indic digits are digits");
    crate::testport::assert_eq(crate::port::cells_at(out, 6), 3, "month 3");
    crate::testport::assert_eq(crate::port::cells_at(out, 7), 14, "day 14");
    sft_run(&crate::testport::text_blob("ISSUED 14 March 2026 BY")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 2, "a day, a word and a year: as it stands");
    crate::testport::assert_eq(crate::port::cells_at(out, 3), 7, "from the day");
    crate::testport::assert_eq(crate::port::cells_at(out, 4), 13, "to the year's end");
    sft_run(&crate::testport::text_blob("ISSUED March 14, 2026 BY")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 2, "a word, a day and a year too");
    crate::testport::assert_eq(crate::port::cells_at(out, 3), 7, "from the word");
    crate::testport::assert_eq(crate::port::cells_at(out, 4), 14, "to the year's end");
    sft_run(&crate::testport::text_blob("14-Mar-2026")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 2, "hyphens between a day, a word and a year");
    sft_run(&crate::testport::text_blob("14 2026")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 0, "a day and a year with no word between is no date");
}
#[test]
fn test_a_name_is_the_first_phrase_of_letters() {
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    sft_run(&crate::testport::text_blob("CITY OF RIVERTON -NOTARY PUBLIC- SEAL")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 0), 0, "the ring's first phrase starts the text");
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 16, "and is sixteen characters, cut at the hyphen");
    crate::testport::assert_eq(crate::port::cells_at(out, 8), 1, "its letters are Latin");
    sft_run(&crate::testport::text_blob("HARBOR COUNTY CLERK · OFFICIAL SEAL")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 19, "a bullet is a separator");
    sft_run(&crate::testport::text_blob("ACME GMBH • HRB 12345 • MUNICH")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 9, "the first phrase, not the register number's");
    sft_run(&crate::testport::text_blob("12345 ★ ACME LIMITED")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 0), 8, "a phrase of digits is no name: the next is");
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 12, "ACME LIMITED");
    sft_run(&crate::testport::text_blob("ООО РОМАШКА • ПЕЧАТЬ")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 11, "Cyrillic: two words");
    crate::testport::assert_eq(crate::port::cells_at(out, 8), 3, "whose letters are Cyrillic");
    sft_run(&crate::testport::text_blob("北京某某有限公司★合同专用章")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 0), 0, "Han letters have no spaces: the phrase before the star");
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 8, "eight letters");
    crate::testport::assert_eq(crate::port::cells_at(out, 8), 10, "of the Han script");
    sft_run(&crate::testport::text_blob("PAID 2026-03-14")[..], et, out, 2, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 0, "a stamp of one word has no name");
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 1, "it has a date");
    sft_run(&crate::testport::text_blob("APPROVED BY ACCOUNTING 2026-03-14")[..], et, out, 2, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 22, "a stamp of three words does");
    crate::testport::assert_eq(crate::port::cells_at(out, 3), 23, "and the date is behind it");
    sft_run(&crate::testport::text_blob("SEAL")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 4, "a seal of one word of four letters is named by it");
    sft_run(&crate::testport::text_blob("OK")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 0, "two letters are none");
    sft_run(&crate::testport::text_blob("Jordan Rivera 2026-03-14")[..], et, out, 3, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 0, "a signature has no name here");
    crate::testport::assert_eq(crate::port::cells_at(out, 2), 0, "and no date");
    sft_run(&crate::testport::text_blob("CO-OP SOCIETY")[..], et, out, 1, 0);
    crate::testport::assert_eq(crate::port::cells_at(out, 1), 13, "a hyphen inside a word is not a separator");
}
#[test]
fn test_the_locale_hint_orders_a_numeric_date() {
    let loc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    sft_put(&crate::testport::text_blob("en-US")[..], loc);
    crate::testport::assert_eq(sf_order(loc), 2, "US: month first");
    sft_put(&crate::testport::text_blob("en_US")[..], loc);
    crate::testport::assert_eq(sf_order(loc), 2, "with an underscore too");
    sft_put(&crate::testport::text_blob("de-DE")[..], loc);
    crate::testport::assert_eq(sf_order(loc), 1, "Germany: day first");
    sft_put(&crate::testport::text_blob("ja")[..], loc);
    crate::testport::assert_eq(sf_order(loc), 1, "a language alone: day first");
    sft_put(&crate::testport::text_blob("")[..], loc);
    crate::testport::assert_eq(sf_order(loc), 0, "no hint: none");
    crate::testport::assert_that(sf_prep(loc, 0) >= 0, "the answer's scratch is made");
    crate::testport::assert_eq(crate::port::cells_len(loc), 32, "of 32 cells");
    sf_prep(loc, 20);
    crate::testport::assert_eq(crate::port::cells_len(loc), 52, "and from another cell, after it");
}
